    /// Parti del lato indicato: true = davanti.
    public static func parts(front: Bool) -> [Part] { front ? self.front : back }

    /// Muscoli che si vedono davanti o dietro (per mostrare solo i lati utili).
    public static func muscles(front: Bool) -> Set<MuscleGroup> { Set(parts(front: front).compactMap(\.muscle)) }

    /// Un comando del tracciato (coordinate della figura).
    public enum Command: Equatable, Sendable {
        case move(Double, Double)
        case curve(Double, Double, Double, Double, Double, Double)
        case close
    }

    /// Legge un tracciato con soli M, C e Z assoluti (quelli generati dallo script). nil se c'e' altro.
    public static func commands(_ path: String) -> [Command]? {
        var out: [Command] = []
        var numbers: [Double] = []
        var current: Character?
        var token = ""
        func flushNumber() -> Bool {
            guard !token.isEmpty else { return true }
            guard let v = Double(token) else { return false }
            numbers.append(v); token = ""; return true
        }
        func flushCommand() -> Bool {
            guard let c = current else { return numbers.isEmpty }
            switch c {
            case "M": guard numbers.count == 2 else { return false }; out.append(.move(numbers[0], numbers[1]))
            case "C": guard numbers.count == 6 else { return false }
                out.append(.curve(numbers[0], numbers[1], numbers[2], numbers[3], numbers[4], numbers[5]))
            case "Z": guard numbers.isEmpty else { return false }; out.append(.close)
            default: return false
            }
            numbers = []; return true
        }
        for ch in path {
            if ch == "M" || ch == "C" || ch == "Z" {
                guard flushNumber(), flushCommand() else { return nil }
                current = ch
            } else if ch == " " || ch == "," {
                guard flushNumber() else { return nil }
            } else if ch == "-" && !token.isEmpty {
                guard flushNumber() else { return nil }
                token.append(ch)
            } else if ch.isNumber || ch == "." || ch == "-" {
                token.append(ch)
            } else {
                return nil
            }
        }
        guard flushNumber(), flushCommand() else { return nil }
        return out
    }
}
